<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Client\Domain\Gateway;

use Closure;
use DateTimeImmutable;
use Civi\Lughauth\Features\OAuth\Client\Domain\DcrInitialAccess;

/**
 * Domain port (outbound gateway) for the initial access tokens that gate dynamic client
 * registration when the tenant policy is "token-required" (task 023, RFC 7591 §3).
 *
 * Tokens are kept only as a digest, bound to a tenant, with an expiration, a maximum number of
 * uses, an optional revocation and optional grant types that take precedence over the tenant
 * ones. The plain token is known only when it is issued.
 */
interface DcrInitialAccessTokenGateway
{
    /**
     * Consumes one use of the token if it belongs to the tenant, is not expired or revoked and
     * has uses left. The validation callback receives the token before the use is spent and may
     * throw to keep it unspent (e.g. for invalid client metadata); the check and the increment
     * are atomic, so two concurrent registrations can never exceed the maximum number of uses.
     *
     * @param Closure(DcrInitialAccess): void $validate
     * @return bool false when the token is not acceptable or its last use was taken meanwhile
     */
    public function consume(string $tenant, string $token, Closure $validate): bool;

    /**
     * Stores a new token for the tenant (a tenant uid; null lets the access policies set the one
     * of the caller) and returns the uid of the record.
     *
     * @param string[]|null $allowedGrantTypes
     */
    public function issue(
        string $token,
        ?string $tenantUid,
        ?string $description,
        DateTimeImmutable $expiresAt,
        int $maxUses,
        ?array $allowedGrantTypes,
    ): string;
}
